window.AUTH=window.AUTH||{};window.AUTH["23-1038"]={"d":"23-1038","id":"2024/23-1038","n":"FDA v. Wages and White Lion Investments, L.L.C.","briefs":[{"k":"petitioner","label":"Brief of petitioner Food and Drug Administration","date":"2024-08-26","url":"https://www.supremecourt.gov/DocketPDF/23/23-1038/323413/20240826164114741_23-1038tsFDA.pdf","side":"pet","n":61},{"k":"respondent","label":"Brief of respondents Wages and White Lion Investments, L.L.C., dba Triton Distribution, et al.","date":"2024-10-07","url":"https://www.supremecourt.gov/DocketPDF/23/23-1038/327672/20241007153644875_23-1038%20Brief%20for%20Respondents.pdf","side":"res","n":71},{"k":"reply","label":"Reply of petitioner Food and Drug Administration","date":"2024-11-06","url":"https://www.supremecourt.gov/DocketPDF/23/23-1038/331324/20241106154759342_23-1038rbUnitedStates.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us2r22_ed9g.pdf","tr":true,"items":[{"t":"case","label":"American Manufacturers Mutual Ins. Co. v. Sullivan","cite":"526 U.S. 40","y":1999,"id":"1998/97-2000","sc":1,"by":{"0":"28"}},{"t":"case","label":"Avail Vapor, LLC v. FDA","cite":"55 F.4th 409","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/55/409/","by":{"0":"17, 21, 23, 32, 37, 43, 46","2":"6, 7, 12, 22"},"q":[{"src":"brief","b":2,"text":"[N]othing can ‘increase’ or ‘decrease’ in a vacuum.","cite":"55 F.4th at 428"},{"src":"brief","b":2,"text":"the daunting task of ensuring that another generation of Americans does not become addicted to nicotine and tobacco products.","cite":"55 F.4th at 428"}]},{"t":"case","label":"Bidi Vapor LLC v. FDA","cite":"47 F.4th 1191","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/47/1191/","by":{"0":"37","1":"51, 53-56"},"q":[{"src":"argument","who":"Mr. Gannon","text":"The one case that's gone the other way here, the Bidi Vapor case from the Eleventh Circuit, specifically cited novel proposals that those applicants had in their application."},{"src":"argument","who":"Mr. Heyer","text":"Well, going back to the 2020 enforcement guidance, which is a document that my friend points to as providing notice on this, the 2020 enforcement guidance doesn't speak -- and I point -- respectfully point the Court to Judge Jones' dissent from the initial panel decision on this and -- and also to the Bidi decision out of the Eleventh Circuit."},{"src":"argument","who":"Mr. Heyer","text":"It also said it in a letter to Bidi Vapor -- we've cited in a footnote, dated May 8th of 2020, just four months before the application deadline."}]},{"t":"case","label":"Bowles v. Seminole Rock & Sand Co.","cite":"325 U.S. 410","y":1945,"id":"scdb/1944-069","sc":1,"by":{"0":"29"}},{"t":"case","label":"Burlington Truck Lines, Inc. v. United States","cite":"371 U.S. 156","y":1962,"id":"1962/27","sc":1,"by":{"0":"40, 41","1":"50"},"q":[{"src":"brief","b":0,"text":"counsel’s discretion for that of the [agency].","cite":"371 U.S. at 169"}]},{"t":"case","label":"Calcutt v. FDIC","cite":"598 U.S. 623","y":2023,"id":"2022/22-714","sc":1,"by":{"0":"40-42","1":"52, 55","2":"16, 17"},"q":[{"src":"brief","b":0,"text":"remand to the agency for additional investigation or explanation.","cite":"598 U.S. 623, 628-629"},{"src":"brief","b":0,"text":"reach its own conclusions based on such an inquiry.","cite":"598 U.S. at 629"},{"src":"brief","b":1,"text":"the proper course, except in rare circumstances, is to remand to the agency for additional investigation or explanation.","cite":"598 U.S. 623, 628-30"},{"src":"brief","b":2,"text":"remand to the agency for additional investigation or explanation.","cite":"598 U.S. 623, 629"},{"src":"argument","who":"Mr. Heyer","text":"Like Calcutt, this is a fact-intensive inquiry, not one where the -- the Court should -- either this Court or the Fifth Circuit should step in and attempt to do the agency's job for it."},{"src":"argument","who":"Justice Alito","text":"Did our decision in Calcutt change harmless error analysis? Was Calcutt a harmless error decision?"}]},{"t":"case","label":"Cheek v. United States","cite":"498 U.S. 192","y":1991,"id":"1990/89-658","sc":1,"by":{"0":"29"},"q":[{"src":"brief","b":0,"text":"a mistake of law is no defense.","cite":"498 U.S. 192, 199"}]},{"t":"case","label":"Christopher v. SmithKline Beecham Corp.","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"by":{"0":"30, 31","1":"28"}},{"t":"case","label":"Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"by":{"0":"26, 30"},"q":[{"src":"brief","b":0,"text":"advise the public prospectively of the manner in which the agency proposes to exercise a discretionary power.","cite":"441 U.S. 281, 302 n.31"}]},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"by":{"0":"37","1":"35"},"q":[{"src":"brief","b":0,"text":"a court of review, not of first view,","cite":"544 U.S. 709, 718 n.7"}]},{"t":"case","label":"DHS v. MacLean","cite":"574 U.S. 383","y":2015,"id":"2014/13-894","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"That is significant because Congress generally acts intentionally when it uses particular language in one section of a statute but omits it in another.","cite":"574 U.S. 383, 391"}]},{"t":"case","label":"Department of Commerce v. New York","cite":"588 U.S. 752","y":2019,"id":"2018/18-966","sc":1,"by":{"0":"16, 40, 45","2":"13, 16, 17, 21, 22"},"q":[{"src":"brief","b":0,"text":"improperly substituted its judgment for that of the agency,","cite":"588 U.S. 752, 775, 777"},{"src":"brief","b":2,"text":"an agency’s stated reasons for acting.","cite":"588 U.S. 752, 780-781"},{"src":"brief","b":2,"text":"limited to evaluating the agency’s contemporaneous explanation in light of the existing administrative record.","cite":"588 U.S. at 780"}]},{"t":"case","label":"Electric Clouds, Inc. v. FDA","cite":"94 F.4th 950","y":2024,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/94/950/","by":{"0":"17, 22, 23, 32, 37, 41, 43, 46","2":"6, 9, 11-13"},"q":[{"src":"brief","b":2,"text":"there’s no evidence that the FDA ever applied","cite":"94 F.4th at 960"}]},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"by":{"0":"18, 30","1":"28, 35, 42"},"q":[{"src":"brief","b":1,"text":"demand[s] that [an agency] display awareness that it is changing position,","cite":"556 U.S. at 515"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"expand[ed] the scope of its enforcement activity,","cite":"556 U. S., at 517"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"good reasons for the new policy","cite":"556 U. S., at 515"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"from a prior policy sub silentio or simply disregard[ed]","cite":"556 U. S., at 515"}]},{"t":"case","label":"FCC v. Prometheus Radio Project","cite":"592 U.S. 414","y":2021,"id":"2020/19-1231","sc":1,"by":{"0":"15-17","1":"46"}},{"t":"case","label":"General Electric Co. v. EPA","cite":"53 F.3d 1324","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/53/1324/","by":{"0":"27","1":"28, 35","2":"3"}},{"t":"case","label":"Grayned v. City of Rockford","cite":"408 U.S. 104","y":1972,"id":"1971/70-5106","sc":1,"by":{"0":"28"}},{"t":"case","label":"Gripum LLC v. FDA","cite":"47 F.4th 553","y":2022,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/47/553/","by":{"0":"17, 23, 43, 44, 46"}},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"by":{"0":"27","2":"3"},"q":[{"src":"brief","b":2,"text":"a criminal law so vague that it fails to give ordinary people fair notice of the conduct it punishes.","cite":"576 U.S. 591, 595"}]},{"t":"case","label":"Kisor v. Wilkie","cite":"588 U.S. 558","y":2019,"id":"2018/18-15","sc":1,"by":{"0":"29"}},{"t":"case","label":"Liquid Labs LLC v. FDA","cite":"52 F.4th 533","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/52/533/","by":{"0":"17, 21-23, 32, 37, 43, 46","2":"6, 12, 14"},"q":[{"src":"brief","b":0,"text":"conflate[d] ‘long-term’ studies with studies examining behavior ‘over time.’","cite":"52 F.4th at 541 n.10"}]},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"591 U.S. 657","y":2020,"id":"2019/19-431","sc":1,"by":{"0":"39","1":"55","2":"15, 16"},"q":[{"src":"brief","b":1,"text":"an administrative agency cannot avoid judicial review by gaming the APA’s remand rules.","cite":"591 U.S. 657"}]},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"144 S. Ct. 2244","y":2024,"id":"2023/22-451","sc":1,"by":{"0":"16, 29, 30","1":"44, 45"},"q":[{"src":"brief","b":0,"text":"the limits of human language and foresight,","cite":"144 S. Ct. at 2257"},{"src":"argument","who":"Mr. Heyer","text":"And -- and, again, this wasn't -- the case wasn't briefed or argued under Loper, but I think the -- the previous guidance is consistent with the language of the statute."}]},{"t":"case","label":"Lotus Vaping Technologies, LLC v. FDA","cite":"73 F.4th 657","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/73/657/","by":{"0":"17, 21, 23, 32, 37, 43, 46","1":"37","2":"6"}},{"t":"case","label":"Magellan Technology, Inc. v. FDA","cite":"70 F.4th 622","y":2023,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/70/622/","by":{"0":"17, 21, 32, 37, 46","2":"12"}},{"t":"case","label":"Morgan Stanley Capital Group Inc. v. Public Utility Dist. No. 1","cite":"554 U.S. 527","y":2008,"id":"2007/06-1457","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"convert judicial review of agency action into a ping-pong game.","cite":"554 U.S. 527, 545"},{"src":"brief","b":0,"text":"To remand would be an idle and useless formality.","cite":"554 U.S. at 545"}]},{"t":"case","label":"NLRB v. Bell Aerospace Co.","cite":"416 U.S. 267","y":1974,"id":"1973/72-1598","sc":1,"by":{"0":"27","2":"4, 5"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"by":{"0":"39"}},{"t":"case","label":"Ohio v. EPA","cite":"144 S. Ct. 2040","y":2024,"url":"https://www.courtlistener.com/c/S.%20Ct./144/2040/","sc":1,"by":{"0":"39"},"q":[{"src":"brief","b":0,"text":"would have reached the same conclusions","cite":"144 S. Ct. 2040, 2057"}]},{"t":"case","label":"Perez v. Mortgage Bankers Ass’n","cite":"575 U.S. 92","y":2015,"id":"2014/13-1041","sc":1,"by":{"0":"29"}},{"t":"case","label":"Prohibition Juice Co. v. FDA","cite":"45 F.4th 8","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/45/8/","by":{"0":"18, 22, 23, 32, 37, 43, 46","1":"37, 55, 56","2":"2, 6, 9, 11, 12, 15"},"q":[{"src":"brief","b":2,"text":"look[] beyond randomized trials and longitudinal studies.","cite":"45 F.4th at 22"},{"src":"brief","b":2,"text":"final determinations were consistent with the 2019 Guidance","cite":"45 F.4th at 21"}]},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"by":{"0":"40","2":"16, 17"},"q":[{"src":"brief","b":0,"text":"be made to do service for an administrative judgment.","cite":"318 U.S. at 88"},{"src":"brief","b":2,"text":"policy or judgment which the agency alone is authorized to make and which it has not made, a judicial judgment cannot be made to do service for an administrative judgment.","cite":"318 U.S. 80, 88"}]},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"by":{"0":"27","1":"34"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"either by general [legislative] rule or by individual order","cite":"332 U. S. 194, 202–203"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"intrude upon the domain which Congress . . . exclusively entrusted to an administrative agency.","cite":"332 U. S., at 196"}]},{"t":"case","label":"Shinseki v. Sanders","cite":"556 U.S. 396","y":2009,"id":"2008/07-1209","sc":1,"by":{"0":"37, 39, 41","1":"51, 52, 55"},"q":[{"src":"brief","b":0,"text":"[T]he burden of showing that an error is harmful normally falls upon the party attacking the agency’s determination.","cite":"556 U.S. 396, 409"},{"src":"brief","b":0,"text":"the same kind of ‘harmless-error’ rule that courts ordinarily apply in civil cases,","cite":"556 U.S. at 406"},{"src":"brief","b":1,"text":"reference to ‘prejudicial error’ is intended to ‘sum up in succinct fashion the ‘harmless error’ rule applied by the courts in the review of lower court decisions as well as of administrative bodies.’","cite":"556 U.S. 396, 406"},{"src":"argument","who":"Mr. Gannon","text":"Well, it -- I mean, the Court's discussion of this in Shinseki against Sanders, which we quote in our brief, says that there's no sort of all-purpose standard for evaluating harmless error."}]},{"t":"case","label":"United States v. L. Cohen Grocery Co.","cite":"255 U.S. 81","y":1921,"id":"scdb/1920-161","sc":1,"by":{"0":"28"}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. NRDC, Inc.","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"by":{"0":"27","2":"4"},"q":[{"src":"brief","b":0,"text":"the maximum procedural requirements which Congress was willing to have the courts impose upon agencies.","cite":"435 U.S. 519, 524"}]},{"t":"case","label":"Waters-Pierce Oil Co. v. Texas","cite":"212 U.S. 86","y":1909,"id":"scdb/1908-063","sc":1,"by":{"0":"39"},"q":[{"src":"brief","b":0,"text":"the judgment would have been the same","cite":"212 U.S. 86, 106"}]},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"27, 28","1":"34, 35"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(4)"],"stext":{"head":"§551. Definitions","paras":[[0,"For the purpose of this subchapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[1,"or except as to the requirements of section 552 of this title—"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1"],[1,"(2) \"person\" includes an individual, partnership, corporation, association, or public or private organization other than an agency;"],[1,"(3) \"party\" includes a person or agency named or admitted as a party, or properly seeking and entitled as of right to be admitted as a party, in an agency proceeding, and a person or agency admitted by an agency as a party for limited purposes;"],[1,"(4) \"rule\" means the whole or a part of an agency statement of general or particular applicability and future effect designed to implement, interpret, or prescribe law or policy or describing the organization, procedure, or practice requirements of an agency and includes the approval or prescription for the future of rates, wages, corporate or financial structures or reorganizations thereof, prices, facilities, appliances, services or allowances therefor or of valuations, costs, or accounting, or practices bearing on any of the foregoing;"],[1,"(5) \"rule making\" means agency process for formulating, amending, or repealing a rule;"],[1,"(6) \"order\" means the whole or a part of a final disposition, whether affirmative, negative, injunctive, or declaratory in form, of an agency in a matter other than rule making but including licensing;"],[1,"(7) \"adjudication\" means agency process for the formulation of an order;"],[1,"(8) \"license\" includes the whole or a part of an agency permit, certificate, approval, registration, charter, membership, statutory exemption or other form of permission;"],[1,"(9) \"licensing\" includes agency process respecting the grant, renewal, denial, revocation, suspension, annulment, withdrawal, limitation, amendment, modification, or conditioning of a license;"],[1,"(10) \"sanction\" includes the whole or a part of an agency—"],[2,"(A) prohibition, requirement, limitation, or other condition affecting the freedom of a person;"],[2,"(B) withholding of relief;"],[2,"(C) imposition of penalty or fine;"],[2,"(D) destruction, taking, seizure, or withholding of property;"],[2,"(E) assessment of damages, reimbursement, restitution, compensation, costs, charges, or fees;"],[2,"(F) requirement, revocation, or suspension of a license; or"],[2,"(G) taking other compulsory or restrictive action;"],[1,"(11) \"relief\" includes the whole or a part of an agency—"],[2,"(A) grant of money, assistance, license, authority, exemption, exception, privilege, or remedy;"],[2,"(B) recognition of a claim, right, immunity, privilege, exemption, or exception; or"],[2,"(C) taking of other action on the application or petition of, and beneficial to, a person;"],[1,"(12) \"agency proceeding\" means an agency process as defined by paragraphs (5), (7), and (9) of this section;"],[1,"(13) \"agency action\" includes the whole or a part of an agency rule, order, license, sanction, relief, or the equivalent or denial thereof, or failure to act; and"],[1,"(14) \"ex parte communication\" means an oral or written communication not on the public record with respect to which reasonable prior notice to all parties is not given, but it shall not include requests for status reports on any matter or proceeding covered by this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/551?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4","1":"47, 47"},"q":[{"src":"brief","b":1,"text":"an agency statement of general or particular applicability and future effect designed to implement, interpret, or prescribe law or policy.","cite":"5 U.S.C. § 551(4)"}]},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","subs":["(b)(4)(A)"],"stext":{"head":"§553. Rule making","paras":[[0,"(a) This section applies, according to the provisions thereof, except to the extent that there is involved—"],[1,"(1) a military or foreign affairs function of the United States; or"],[1,"(2) a matter relating to agency management or personnel or to public property, loans, grants, benefits, or contracts."],[0,"(b) General notice of proposed rule making shall be published in the Federal Register, unless persons subject thereto are named and either personally served or otherwise have actual notice thereof in accordance with law. The notice shall include—"],[1,"(1) a statement of the time, place, and nature of public rule making proceedings;"],[1,"(2) reference to the legal authority under which the rule is proposed;"],[1,"(3) either the terms or substance of the proposed rule or a description of the subjects and issues involved; and"],[1,"(4) the Internet address of a summary of not more than 100 words in length of the proposed rule, in plain language, that shall be posted on the Internet website under section 206(d) of the E-Government Act of 2002 (44 U.S.C. 3501 note) (commonly known as regulations.gov)."],[0,"Except when notice or hearing is required by statute, this subsection does not apply—"],[1,"(A) to interpretative rules, general statements of policy, or rules of agency organization, procedure, or practice; or"],[1,"(B) when the agency for good cause finds (and incorporates the finding and a brief statement of reasons therefor in the rules issued) that notice and public procedure thereon are impracticable, unnecessary, or contrary to the public interest."],[0,"(c) After notice required by this section, the agency shall give interested persons an opportunity to participate in the rule making through submission of written data, views, or arguments with or without opportunity for oral presentation. After consideration of the relevant matter presented, the agency shall incorporate in the rules adopted a concise general statement of their basis and purpose. When rules are required by statute to be made on the record after opportunity for an agency hearing, sections 556 and 557 of this title apply instead of this subsection."],[0,"(d) The required publication or service of a substantive rule shall be made not less than 30 days before its effective date, except—"],[1,"(1) a substantive rule which grants or recognizes an exemption or relieves a restriction;"],[1,"(2) interpretative rules and statements of policy; or"],[1,"(3) as otherwise provided by the agency for good cause found and published with the rule."],[0,"(e) Each agency shall give an interested person the right to petition for the issuance, amendment, or repeal of a rule."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/553?type=usc&year=mostrecent&link-type=html"},"by":{"0":"26","1":"48, 48"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 2","1":"35, 51","2":"15"},"q":[{"src":"brief","b":0,"text":"determine the meaning or applicability of the terms of an agency action.","cite":"5 U.S.C. 706"},{"src":"brief","b":0,"text":"due account shall be taken of the rule of prejudicial error.","cite":"5 U.S.C. 706"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law.","cite":"5 U. S. C. § 706(2)(A)"}]},{"t":"usc","label":"15 U.S.C. § 57b-4","url":"https://www.law.cornell.edu/uscode/text/15/57b-4","subs":["(b)"],"by":{"0":"29"}},{"t":"usc","label":"21 U.S.C. § 387a","url":"https://www.law.cornell.edu/uscode/text/21/387a","subs":["(b)"],"stext":{"head":"§387a. FDA authority over tobacco products","paras":[[0,"(a) In general"],[0,"Tobacco products, including modified risk tobacco products for which an order has been issued in accordance with section 387k of this title, shall be regulated by the Secretary under this subchapter and shall not be subject to the provisions of subchapter V."],[0,"(b) Applicability"],[0,"This subchapter shall apply to all cigarettes, cigarette tobacco, roll-your-own tobacco, and smokeless tobacco and to any other tobacco products that the Secretary by regulation deems to be subject to this subchapter. This subchapter shall also apply to any tobacco product containing nicotine that is not made or derived from tobacco."],[0,"(c) Scope"],[0,"(1) In general"],[1,"Nothing in this subchapter, or any policy issued or regulation promulgated thereunder, or in sections 101(a), 102, or 103 of title I, title II, or title III of the Family Smoking Prevention and Tobacco Control Act, shall be construed to affect, expand, or limit the Secretary's authority over (including the authority to determine whether products may be regulated), or the regulation of, products under this chapter that are not tobacco products under subchapter V or any other subchapter."],[0,"(2) Limitation of authority"],[0,"(A) In general"],[2,"The provisions of this subchapter shall not apply to tobacco leaf that is not in the possession of a manufacturer of tobacco products, or to the producers of tobacco leaf, including tobacco growers, tobacco warehouses, and tobacco grower cooperatives, nor shall any employee of the Food and Drug Administration have any authority to enter onto a farm owned by a producer of tobacco leaf without the written consent of such producer."],[0,"(B) Exception"],[2,"Notwithstanding subparagraph (A), if a producer of tobacco leaf is also a tobacco product manufacturer or controlled by a tobacco product manufacturer, the producer shall be subject to this subchapter in the producer's capacity as a manufacturer. The exception in this subparagraph shall not apply to a producer of tobacco leaf who grows tobacco under a contract with a tobacco product manufacturer and who is not otherwise engaged in the manufacturing process."],[0,"(C) Rule of construction"],[2,"Nothing in this subchapter shall be construed to grant the Secretary authority to promulgate regulations on any matter that involves the production of tobacco leaf or a producer thereof, other than activities by a manufacturer affecting production."],[0,"(d) Rulemaking procedures"],[0,"Each rulemaking under this subchapter shall be in accordance with chapter 5 of title 5. This subsection shall not be construed to affect the rulemaking provisions of section 102(a) of the Family Smoking Prevention and Tobacco Control Act [21 U.S.C. 387a–1(a)]."],[0,"(e) Center for tobacco products"],[0,"Not later than 90 days after June 22, 2009, the Secretary shall establish within the Food and Drug Administration the Center for Tobacco Products, which shall report to the Commissioner of Food and Drugs in the same manner as the other agency centers within the Food and Drug Administration. The Center shall be responsible for the implementation of this subchapter and related matters assigned by the Commissioner."],[0,"(f) Office to assist small tobacco product manufacturers"],[0,"The Secretary shall establish within the Food and Drug Administration an identifiable office to provide technical and other nonfinancial assistance to small tobacco product manufacturers to assist them in complying with the requirements of this chapter."],[0,"(g) Consultation prior to rulemaking"],[0,"Prior to promulgating rules under this subchapter, the Secretary shall endeavor to consult with other Federal agencies as appropriate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/387a?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 5","1":"9"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"cigarettes, cigarette tobacco, roll-your-own tobacco, and smokeless tobacco.","cite":"21 U. S. C. § 387a(b)"}]},{"t":"usc","label":"21 U.S.C. § 387j","url":"https://www.law.cornell.edu/uscode/text/21/387j","subs":["(a)(1)","(a)(2)(A)","(c)(2)","(c)(2)(A)","(c)(4)","(c)(4)(A)","(c)(4)(B)","(c)(5)(A)","(c)(5)(B)","(b)(1)(A)"],"stext":{"head":"§387j. Application for review of certain tobacco products","paras":[[0,"(a) In general"],[0,"(1) New tobacco product defined"],[1,"For purposes of this section the term \"new tobacco product\" means—"],[2,"(A) any tobacco product (including those products in test markets) that was not commercially marketed in the United States as of February 15, 2007; or"],[2,"(B) any modification (including a change in design, any component, any part, or any constituent, including a smoke constituent, or in the content, delivery or form of nicotine, or any other additive or ingredient) of a tobacco product where the modified product was commercially marketed in the United States after February 15, 2007."],[0,"(2) Premarket review required"],[0,"(A) New products"],[2,"An order under subsection (c)(1)(A)(i) for a new tobacco product is required unless—"],[3,"(i) the manufacturer has submitted a report under section 387e(j) of this title; and the Secretary has issued an order that the tobacco product—"],[4,"(I) is substantially equivalent to a tobacco product commercially marketed (other than for test marketing) in the United States as of February 15, 2007; and"],[4,"(II) is in compliance with the requirements of this chapter; or"],[3,"(ii) the tobacco product is exempt from the requirements of section 387e(j) of this title pursuant to a regulation issued under section 387e(j)(3) of this title."],[0,"(B) Application to certain post-February 15, 2007, products"],[2,"Subparagraph (A) shall not apply to a tobacco product—"],[3,"(i) that was first introduced or delivered for introduction into interstate commerce for commercial distribution in the United States after February 15, 2007, and prior to the date that is 21 months after June 22, 2009; and"],[3,"(ii) for which a report was submitted under section 387e(j) of this title within such 21-month period,"],[2,"except that subparagraph (A) shall apply to the tobacco product if the Secretary issues an order that the tobacco product is not substantially equivalent."],[0,"(3) Substantially equivalent defined"],[0,"(A) In general"],[2,"In this section and section 387e(j) of this title, the term \"substantially equivalent\" or \"substantial equivalence\" means, with respect to the tobacco product being compared to the predicate tobacco product, that the Secretary by order has found that the tobacco product—"],[3,"(i) has the same characteristics as the predicate tobacco product; or"],[3,"(ii) has different characteristics and the information submitted contains information, including clinical data if deemed necessary by the Secretary, that demonstrates that it is not appropriate to regulate the product under this section because the product does not raise different questions of public health."],[0,"(B) Characteristics"],[2,"In subparagraph (A), the term \"characteristics\" means the materials, ingredients, design, composition, heating source, or other features of a tobacco product."],[0,"(C) Limitation"],[2,"A tobacco product may not be found to be substantially equivalent to a predicate tobacco product that has been removed from the market at the initiative of the Secretary or that has been determined by a judicial order to be misbranded or adulterated."],[0,"(4) Health information"],[0,"(A) Summary"],[2,"As part of a submission under section 387e(j) of this title respecting a tobacco product, the person required to file a premarket notification under such section shall provide an adequate summary of any health information related to the tobacco product or state that such information will be made available upon request by any person."],[0,"(B) Required information"],[2,"Any summary under subparagraph (A) respecting a tobacco product shall contain detailed information regarding data concerning adverse health effects and shall be made available to the public by the Secretary within 30 days of the issuance of a determination that such tobacco product is substantially equivalent to another tobacco product."],[0,"(b) Application"],[0,"(1) Contents"],[1,"An application under this section shall contain—"],[2,"(A) full reports of all information, published or known to, or which should reasonably be known to, the applicant, concerning investigations which have been made to show the health risks of such tobacco product and whether such tobacco product presents less risk than other tobacco products;"],[2,"(B) a full statement of the components, ingredients, additives, and properties, and of the principle or principles of operation, of such tobacco product;"],[2,"(C) a full description of the methods used in, and the facilities and controls used for, the manufacture, processing, and, when relevant, packing and installation of, such tobacco product;"],[2,"(D) an identifying reference to any tobacco product standard under section 387g of this title which would be applicable to any aspect of such tobacco product, and either adequate information to show that such aspect of such tobacco product fully meets such tobacco product standard or adequate information to justify any deviation from such standard;"],[2,"(E) such samples of such tobacco product and of components thereof as the Secretary may reasonably require;"],[2,"(F) specimens of the labeling proposed to be used for such tobacco product; and"],[2,"(G) such other information relevant to the subject matter of the application as the Secretary may require."],[0,"(2) Referral to Tobacco Products Scientific Advisory Committee"],[1,"Upon receipt of an application meeting the requirements set forth in paragraph (1), the Secretary—"],[2,"(A) may, on the Secretary's own initiative; or"],[2,"(B) may, upon the request of an applicant,"],[1,"refer such application to the Tobacco Products Scientific Advisory Committee for reference and for submission (within such period as the Secretary may establish) of a report and recommendation respecting the application, together with all underlying data and the reasons or basis for the recommendation."],[0,"(c) Action on application"],[0,"(1) Deadline"],[0,"(A) In general"],[2,"As promptly as possible, but in no event later than 180 days after the receipt of an application under subsection (b), the Secretary, after considering the report and recommendation submitted under subsection (b)(2), shall—"],[3,"(i) issue an order that the new product may be introduced or delivered for introduction into interstate commerce if the Secretary finds that none of the grounds specified in paragraph (2) of this subsection applies; or"],[3,"(ii) issue an order that the new product may not be introduced or delivered for introduction into interstate commerce if the Secretary finds (and sets forth the basis for such finding as part of or accompanying such denial) that 1 or more grounds for denial specified in paragraph (2) of this subsection apply."],[0,"(B) Restrictions on sale and distribution"],[2,"An order under subparagraph (A)(i) may require that the sale and distribution of the tobacco product be restricted but only to the extent that the sale and distribution of a tobacco product may be restricted under a regulation under section 387f(d) of this title."],[0,"(2) Denial of application"],[1,"The Secretary shall deny an application submitted under subsection (b) if, upon the basis of the information submitted to the Secretary as part of the application and any other information before the Secretary with respect to such tobacco product, the Secretary finds that—"],[2,"(A) there is a lack of a showing that permitting such tobacco product to be marketed would be appropriate for the protection of the public health;"],[2,"(B) the methods used in, or the facilities or controls used for, the manufacture, processing, or packing of such tobacco product do not conform to the requirements of section 387f(e) of this title;"],[2,"(C) based on a fair evaluation of all material facts, the proposed labeling is false or misleading in any particular; or"],[2,"(D) such tobacco product is not shown to conform in all respects to a tobacco product standard in effect under section 387g of this title, and there is a lack of adequate information to justify the deviation from such standard."],[0,"(3) Denial information"],[1,"Any denial of an application shall, insofar as the Secretary determines to be practicable, be accompanied by a statement informing the applicant of the measures required to remove such application from deniable form (which measures may include further research by the applicant in accordance with 1 or more protocols prescribed by the Secretary)."],[0,"(4) Basis for finding"],[1,"For purposes of this section, the finding as to whether the marketing of a tobacco product for which an application has been submitted is appropriate for the protection of the public health shall be determined with respect to the risks and benefits to the population as a whole, including users and nonusers of the tobacco product, and taking into account—"],[2,"(A) the increased or decreased likelihood that existing users of tobacco products will stop using such products; and"],[2,"(B) the increased or decreased likelihood that those who do not use tobacco products will start using such products."],[0,"(5) Basis for action"],[0,"(A) Investigations"],[2,"For purposes of paragraph (2)(A), whether permitting a tobacco product to be marketed would be appropriate for the protection of the public health shall, when appropriate, be determined on the basis of well-controlled investigations, which may include 1 or more clinical investigations by experts qualified by training and experience to evaluate the tobacco product."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/387j?type=usc&year=mostrecent&link-type=html"},"by":{"0":"26, 26, 26, 26, 26, 26, 26, 26, 26","1":"3, 9, 3, 4, 49","2":"4, 7, 7, 6, 8"},"q":[{"src":"brief","b":0,"text":"would be appropriate for the protection of the public health.","cite":"21 U.S.C. 387j(c)(2)(A)"},{"src":"brief","b":0,"text":"likelihood that those who do not use tobacco products will start using such products.","cite":"21 U.S.C. 387j(c)(4)"},{"src":"brief","b":1,"text":"appropriate for the protection of the public health.","cite":"21 U.S.C. § 387j(c)(2)(A)"},{"src":"brief","b":1,"text":"(A) the increased or decreased likelihood that existing users of tobacco products will stop using such products; and (B) the increased or decreased likelihood that those who do not use tobacco products will start using such products.","cite":"21 U.S.C. § 387j(c)(4)"},{"src":"brief","b":2,"text":"the increased or decreased likelihood that those who do not use tobacco products will start using such products.","cite":"21 U.S.C. 387j(c)(4)"},{"src":"brief","b":2,"text":"whether [its] tobacco product presents less risk than other tobacco products.","cite":"21 U.S.C. 387j(b)(1)(A)"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"appropriate for the protection of the public health.","cite":"21 U. S. C. § 387j(c)(2)(A)"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"presents less risk than other tobacco products.","cite":"21 U. S. C. § 387j(b)(1)(A)"}]},{"t":"usc","label":"21 U.S.C. § 387k","url":"https://www.law.cornell.edu/uscode/text/21/387k","subs":["(l)(1)"],"by":{"0":"26"}},{"t":"usc","label":"21 U.S.C. § 387l","url":"https://www.law.cornell.edu/uscode/text/21/387l","subs":["(a)(1)(B)","(b)"],"by":{"0":"3, 3"}},{"t":"usc","label":"21 U.S.C. § 393","url":"https://www.law.cornell.edu/uscode/text/21/393","subs":["(d)(2)"],"by":{"0":"3"}},{"t":"usc","label":"29 U.S.C. § 259","url":"https://www.law.cornell.edu/uscode/text/29/259","subs":["(a)"],"by":{"0":"29"}},{"t":"usc","label":"52 U.S.C. § 30111","url":"https://www.law.cornell.edu/uscode/text/52/30111","subs":["(e)"],"by":{"0":"29"}},{"t":"reg","label":"81 Fed. Reg. 28,974","url":"https://www.govinfo.gov/link/fr/81/28974","by":{"0":"5","1":"9, 10"}},{"t":"reg","label":"84 Fed. Reg. 50,566","url":"https://www.govinfo.gov/link/fr/84/50566","by":{"0":"33","1":"12, 31, 32, 41, 49, 50"}},{"t":"case","label":"Am. Acad. of Pediatrics v. FDA","cite":"399 F. Supp. 3d 479","y":2019,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/399/479/","by":{"1":"10","2":"22"}},{"t":"case","label":"Appalachian Power Co. v. EPA","cite":"208 F.3d 1015","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/208/1015/","by":{"1":"31"}},{"t":"case","label":"DHS v. Regents of the Univ. of Cal.","cite":"591 U.S. 1","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/1/","sc":1,"by":{"1":"39, 41-43, 55"},"q":[{"src":"brief","b":1,"text":"When an agency changes course . . . it must be cognizant that longstanding policies may have engendered serious reliance interests that must be taken into account.","cite":"591 U.S. at 30"}]},{"t":"case","label":"Dep’t of Commerce v. New York","cite":"588 U.S. 752","y":2019,"url":"https://supreme.justia.com/cases/federal/us/588/752/","sc":1,"by":{"1":"55"}},{"t":"case","label":"Egbert v. Boule","cite":"596 U.S. 482","y":2022,"id":"2021/21-147","sc":1,"by":{"1":"38"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"579 U.S. 211","y":2016,"id":"2015/15-415","sc":1,"by":{"1":"40, 42, 46"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"be cognizant that longstanding policies may have `engendered serious reliance interests that must be taken into account.'","cite":"579 U. S., at 221"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"decades of industry reliance on [an agency's] prior policy.","cite":"579 U. S., at 222"}]},{"t":"case","label":"ExxonMobil Pipeline Co. v. United States DOT","cite":"867 F.3d 564","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/867/564/","by":{"1":"28","2":"3"}},{"t":"case","label":"March v. Or. Nat. Res. Council","cite":"490 U.S. 360","y":1989,"id":"1988/87-1704","sc":1,"by":{"1":"29"}},{"t":"case","label":"Martin v. OSHRC","cite":"499 U.S. 144","y":1991,"id":"1990/89-1541","sc":1,"by":{"1":"28"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"by":{"1":"55"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"by":{"1":"50, 57"},"q":[{"src":"brief","b":1,"text":"entirely failed to consider an important aspect of the problem.","cite":"463 U.S. 29, 43"},{"src":"brief","b":1,"text":"[i]t is well established that an agency’s action must be upheld, if at all, on the basis articulated by the agency itself.","cite":"463 U.S. at 50"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"examine[d] the relevant data and articulate[d] a satisfactory explanation for its action including a rational connection between the facts found and the choice made.","cite":"463 U. S. 29, 43"}]},{"t":"case","label":"Nat’l Ass’n of Home Builders v. U.S. Army Corp of Eng’rs","cite":"417 F.3d 1272","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/417/1272/","by":{"1":"48"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"by":{"1":"34, 35"}},{"t":"case","label":"Radio Athens, Inc. v. FCC","cite":"401 F.2d 398","y":1968,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/401/398/","by":{"1":"34","2":"3"}},{"t":"case","label":"R.J. Reynolds Vapor Co. v. FDA","cite":"65 F.4th 182","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/65/182/","by":{"1":"48, 49"},"q":[{"src":"brief","b":1,"text":"took away FDA reviewers’ former discretion to consider individual PMTAs solely on their merits and instead requires a cursory, box-checking review.","cite":"65 F.4th at 193"}]},{"t":"case","label":"Rollins Env’t Servs. (NJ), Inc. v. EPA","cite":"937 F.2d 649","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/937/649/","by":{"1":"28"}},{"t":"case","label":"Safari Club Int’l v. Zinke","cite":"878 F.3d 316","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/878/316/","by":{"1":"48"},"q":[{"src":"brief","b":1,"text":"may not escape [the notice-andcomment] requirements of [5 U.S.C. §] 553 by labeling its rule an ‘adjudication.’","cite":"878 F.3d 316, 332"}]},{"t":"case","label":"Salzer v. FCC","cite":"778 F.2d 869","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/778/869/","by":{"1":"44"},"q":[{"src":"argument","who":"Mr. Heyer","text":"Circuit line of case law, and I would point the Court specifically to the Salzer case, which is referenced heavily in satellite broadcasting."},{"src":"argument","who":"Mr. Heyer","text":"In Salzer -- the reason I go to Salzer, which predates satellite broadcasting, that was absolutely a denial of a benefit. Here, it's even more -- as the Fifth Circuit point out -- even more of a sanction, even more punitive."}]},{"t":"case","label":"Satellite Broadcasting Co. v. FCC","cite":"824 F.2d 1","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/824/1/","by":{"1":"29, 35, 44","2":"3, 4"},"q":[{"src":"brief","b":1,"text":"dismissal of an application . . . is a sufficiently grave sanction to trigger this duty to provide clear notice.","cite":"824 F.2d 1, 3"},{"src":"brief","b":1,"text":"wishes to use [its own] interpretation to cut off a party’s right, it must give full notice of its interpretation.","cite":"824 F.2d at 4"}]},{"t":"case","label":"St. Vincent Randolph Hosp., Inc. v. Price","cite":"869 F.3d 510","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/869/510/","by":{"1":"55"},"q":[{"src":"brief","b":1,"text":"the agency just asserts an ipse dixit,","cite":"869 F.3d 510, 513"}]},{"t":"case","label":"Syncor Int’l Corp. v. Shalala","cite":"127 F.3d 90","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/127/90/","by":{"1":"48"}},{"t":"case","label":"Thigpen v. Roberts","cite":"468 U.S. 27","y":1984,"id":"1983/82-1330","sc":1,"by":{"1":"49"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"by":{"1":"28"}},{"t":"case","label":"Vapor Technology Ass’n v. FDA","cite":"977 F.3d 496","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/977/496/","by":{"1":"10"}},{"t":"law","label":"Family Smoking Prevention and Tobacco Control Act, Pub. L. No. 111-31","url":"https://www.govinfo.gov/link/plaw/111/public/31","by":{"1":"3","2":"1"}},{"t":"usc","label":"21 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/21/321","subs":["(rr)(1)(2010)","(rr)(1)(2022)"],"stext":{"head":"§321. Definitions; generally","paras":[[0,"For the purposes of this chapter—"],[0,"(a)(1) The term \"State\", except as used in the last sentence of section 372(a) of this title, means any State or Territory of the United States, the District of Columbia, and the Commonwealth of Puerto Rico."],[0,"(2) The term \"Territory\" means any Territory or possession of the United States, including the District of Columbia, and excluding the Commonwealth of Puerto Rico and the Canal Zone."],[0,"(b) The term \"interstate commerce\" means (1) commerce between any State or Territory and any place outside thereof, and (2) commerce within the District of Columbia or within any other Territory not organized with a legislative body."],[0,"(c) The term \"Department\" means Department of Health and Human Services."],[0,"(d) The term \"Secretary\" means the Secretary of Health and Human Services."],[0,"(e) The term \"person\" includes individual, partnership, corporation, and association."],[0,"(f) The term \"food\" means (1) articles used for food or drink for man or other animals, (2) chewing gum, and (3) articles used for components of any such article."],[0,"(g)(1) The term \"drug\" means (A) articles recognized in the official United States Pharmacopoeia,1 official Homoeopathic Pharmacopoeia of the United States, or official National Formulary, or any supplement to any of them; and (B) articles intended for use in the diagnosis, cure, mitigation, treatment, or prevention of disease in man or other animals; and (C) articles (other than food) intended to affect the structure or any function of the body of man or other animals; and (D) articles intended for use as a component of any article specified in clause (A), (B), or (C). A food or dietary supplement for which a claim, subject to sections 343(r)(1)(B) and 343(r)(3) of this title or sections 343(r)(1)(B) and 343(r)(5)(D) of this title, is made in accordance with the requirements of section 343(r) of this title is not a drug solely because the label or the labeling contains such a claim. A food, dietary ingredient, or dietary supplement for which a truthful and not misleading statement is made in accordance with section 343(r)(6) of this title is not a drug under clause (C) solely because the label or the labeling contains such a statement."],[0,"(2) The term \"counterfeit drug\" means a drug which, or the container or labeling of which, without authorization, bears the trademark, trade name, or other identifying mark, imprint, or device, or any likeness thereof, of a drug manufacturer, processor, packer, or distributor other than the person or persons who in fact manufactured, processed, packed, or distributed such drug and which thereby falsely purports or is represented to be the product of, or to have been packed or distributed by, such other drug manufacturer, processor, packer, or distributor."],[0,"(h)(1) The term \"device\" (except when used in paragraph (n) of this section and in sections 331(i), 343(f), 352(c), and 362(c) of this title) means an instrument, apparatus, implement, machine, contrivance, implant, in vitro reagent, or other similar or related article, including any component, part, or accessory, which is—"],[1,"(A) recognized in the official National Formulary, or the United States Pharmacopeia, or any supplement to them,"],[1,"(B) intended for use in the diagnosis of disease or other conditions, or in the cure, mitigation, treatment, or prevention of disease, in man or other animals, or"],[1,"(C) intended to affect the structure or any function of the body of man or other animals, and"],[0,"which does not achieve its primary intended purposes through chemical action within or on the body of man or other animals and which is not dependent upon being metabolized for the achievement of its primary intended purposes. The term \"device\" does not include software functions excluded pursuant to section 360j(o) of this title."],[0,"(2) The term \"counterfeit device\" means a device which, or the container, packaging, or labeling of which, without authorization, bears a trademark, trade name, or other identifying mark or imprint, or any likeness thereof, or is manufactured using a design, of a device manufacturer, processor, packer, or distributor other than the person or persons who in fact manufactured, processed, packed, or distributed such device and which thereby falsely purports or is represented to be the product of, or to have been packed or distributed by, such other device manufacturer, processor, packer, or distributor."],[0,"(i) The term \"cosmetic\" means (1) articles intended to be rubbed, poured, sprinkled, or sprayed on, introduced into, or otherwise applied to the human body or any part thereof for cleansing, beautifying, promoting attractiveness, or altering the appearance, and (2) articles intended for use as a component of any such articles; except that such term shall not include soap."],[0,"(j) The term \"official compendium\" means the official United States Pharmacopoeia, official Homoeopathic Pharmacopoeia of the United States, official National Formulary, or any supplement to any of them."],[0,"(k) The term \"label\" means a display of written, printed, or graphic matter upon the immediate container of any article; and a requirement made by or under authority of this chapter that any word, statement, or other information appear on the label shall not be considered to be complied with unless such word, statement, or other information also appears on the outside container or wrapper, if any there be, of the retail package of such article, or is easily legible through the outside container or wrapper."],[0,"(l) The term \"immediate container\" does not include package liners."],[0,"(m) The term \"labeling\" means all labels and other written, printed, or graphic matter (1) upon any article or any of its containers or wrappers, or (2) accompanying such article."],[0,"(n) If an article is alleged to be misbranded because the labeling or advertising is misleading, then in determining whether the labeling or advertising is misleading there shall be taken into account (among other things) not only representations made or suggested by statement, word, design, device, or any combination thereof, but also the extent to which the labeling or advertising fails to reveal facts material in the light of such representations or material with respect to consequences which may result from the use of the article to which the labeling or advertising relates under the conditions of use prescribed in the labeling or advertising thereof or under such conditions of use as are customary or usual."],[0,"(o) The representation of a drug, in its labeling, as an antiseptic shall be considered to be a representation that it is a germicide, except in the case of a drug purporting to be, or represented as, an antiseptic for inhibitory use as a wet dressing, ointment, dusting powder, or such other use as involves prolonged contact with the body."],[0,"(p) The term \"new drug\" means—"],[1,"(1) Any drug (except a new animal drug or an animal feed bearing or containing a new animal drug) the composition of which is such that such drug is not generally recognized, among experts qualified by scientific training and experience to evaluate the safety and effectiveness of drugs, as safe and effective for use under the conditions prescribed, recommended, or suggested in the labeling thereof, except that such a drug not so recognized shall not be deemed to be a \"new drug\" if at any time prior to June 25, 1938, it was subject to the Food and Drugs Act of June 30, 1906, as amended, and if at such time its labeling contained the same representations concerning the conditions of its use; or"],[1,"(2) Any drug (except a new animal drug or an animal feed bearing or containing a new animal drug) the composition of which is such that such drug, as a result of investigations to determine its safety and effectiveness for use under such conditions, has become so recognized, but which has not, otherwise than in such investigations, been used to a material extent or for a material time under such conditions."],[0,"(q)(1)(A) Except as provided in clause (B), the term \"pesticide chemical\" means any substance that is a pesticide within the meaning of the Federal Insecticide, Fungicide, and Rodenticide Act [7 U.S.C. 136 et seq.], including all active and inert ingredients of such pesticide. Notwithstanding any other provision of law, the term \"pesticide\" within such meaning includes ethylene oxide and propylene oxide when such substances are applied on food."],[0,"(B) In the case of the use, with respect to food, of a substance described in clause (A) to prevent, destroy, repel, or mitigate microorganisms (including bacteria, viruses, fungi, protozoa, algae, and slime), the following applies for purposes of clause (A):"],[1,"(i) The definition in such clause for the term \"pesticide chemical\" does not include the substance if the substance is applied for such use on food, or the substance is included for such use in water that comes into contact with the food, in the preparing, packing, or holding of the food for commercial purposes. The substance is not excluded under this subclause from such definition if the substance is ethylene oxide or propylene oxide, and is applied for such use on food. The substance is not so excluded if the substance is applied for such use on a raw agricultural commodity, or the substance is included for such use in water that comes into contact with the commodity, as follows:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/321?type=usc&year=mostrecent&link-type=html"},"by":{"1":"9, 9"},"q":[{"src":"brief","b":1,"text":"any product made or derived from tobacco that is intended for human consumption, including any component, part, or accessory of a tobacco product.","cite":"21 U.S.C. § 321(rr)(1)"},{"src":"brief","b":1,"text":"containing nicotine derived from any source.","cite":"21 U.S.C. § 321(rr)(1)"}]},{"t":"usc","label":"21 U.S.C. § 331","url":"https://www.law.cornell.edu/uscode/text/21/331","subs":["(a)"],"by":{"1":"9, 43"}},{"t":"usc","label":"21 U.S.C. § 333","url":"https://www.law.cornell.edu/uscode/text/21/333","subs":["(a)(1)","(f)(9)"],"by":{"1":"9, 43, 9, 43"}},{"t":"usc","label":"21 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/21/371","subs":["(h)(1)(C)(i)"],"by":{"1":"48"}},{"t":"usc","label":"21 U.S.C. § 387b","url":"https://www.law.cornell.edu/uscode/text/21/387b","subs":["(6)(A)"],"by":{"1":"9, 43"}},{"t":"usc","label":"21 U.S.C. § 387g","url":"https://www.law.cornell.edu/uscode/text/21/387g","subs":["(a)(1)(A)","(a)(4)(B)(i)","(c)","(d)"],"by":{"1":"49, 49, 49, 49"}},{"t":"usc","label":"21 U.S.C. § 387r","url":"https://www.law.cornell.edu/uscode/text/21/387r","subs":["(b)(1)"],"by":{"1":"3"},"q":[{"src":"brief","b":1,"text":"encourage the development of innovative products,","cite":"21 U.S.C. § 387r(b)(1)"}]},{"t":"reg","label":"1 C.F.R. § 18.12","url":"https://www.ecfr.gov/current/title-1/section-18.12","by":{"1":"47"}},{"t":"reg","label":"21 C.F.R. § 10.115","url":"https://www.ecfr.gov/current/title-21/section-10.115","subs":["(c)(1)","(g)"],"by":{"1":"48, 48"}},{"t":"reg","label":"21 C.F.R. § 1114.9","url":"https://www.ecfr.gov/current/title-21/section-1114.9","by":{"1":"41"}},{"t":"reg","label":"21 C.F.R. § 1143.1","url":"https://www.ecfr.gov/current/title-21/section-1143.1","by":{"1":"9"}},{"t":"reg","label":"FDA, Advance Notice of Proposed Rulemaking, Regulation of Flavors in Tobacco Products, 83 Fed. Reg. 12294","url":"https://www.govinfo.gov/link/fr/83/12294","by":{"1":"12"}},{"t":"reg","label":"FDA, Premarket Tobacco Product Applications and Recordkeeping Requirements, Final Rule, 86 Fed. Reg. 55300","url":"https://www.govinfo.gov/link/fr/86/55300","by":{"1":"24, 50"}},{"t":"case","label":"Atlantic Marine Construction Co. v. U.S. District Court","cite":"571 U.S. 49","y":2013,"id":"2013/12-929","sc":1,"by":{"2":"22"}},{"t":"case","label":"BMW of North America, Inc. v. Gore","cite":"517 U.S. 559","y":1996,"id":"1995/94-896","sc":1,"by":{"2":"3"},"q":[{"src":"brief","b":2,"text":"the conduct that will subject him to punishment.","cite":"517 U.S. 559, 574"}]},{"t":"case","label":"Erie-Lackawanna R.R. Co. v. United States","cite":"279 F. Supp. 316","y":1967,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./279/316/","by":{"2":"17"},"q":[{"src":"brief","b":2,"text":"while court and agency engage in a nigh endless game of battledore and shuttlecock.","cite":"279 F. Supp. 316, 354-355"}]},{"t":"case","label":"National Security Archive v. CIA","cite":"752 F.3d 460","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/752/460/","by":{"2":"12"},"q":[{"src":"brief","b":2,"text":"should be judged by what they decided, not for matters they considered before making up their minds.","cite":"752 F.3d 460, 462"}]},{"t":"case","label":"United States v. Chemical Foundation, Inc.","cite":"272 U.S. 1","y":1926,"id":"scdb/1926-001","sc":1,"by":{"2":"13"}},{"t":"case","label":"United States v. Title Insurance & Trust Co.","cite":"265 U.S. 472","y":1924,"id":"scdb/1923-181","sc":1,"by":{"2":"16"},"q":[{"src":"brief","b":2,"text":"the ruling on neither is obiter, but each is the judgment of the court, and of equal validity with the other.","cite":"265 U.S. 472, 486"}]},{"t":"const","label":"Amendment XIV","clauses":[["due-process-14","Due Process Clause (Fourteenth Amendment)"]],"by":{"2":"3"}}]};